// Weather icons. The pictures are generated by tools/make_weather_icons.py and stored in
// weather_icons.c; this file only looks up the right one and shows it.
#include "icons.h"

#include <cstring>
#include <vector>

#include "weather_icons.h"

namespace {

// One LVGL image description per stored icon, built the first time it is needed.
const lv_image_dsc_t* picture(const char* key, int size) {
    static std::vector<lv_image_dsc_t> made;
    if (made.empty()) {
        made.resize(weather_icon_count);
        for (int i = 0; i < weather_icon_count; i++) {
            const weather_icon_t& icon = weather_icons[i];
            lv_image_dsc_t& d = made[i];
            memset(&d, 0, sizeof d);
            d.header.magic = LV_IMAGE_HEADER_MAGIC;
            d.header.cf = LV_COLOR_FORMAT_RGB565A8;
            d.header.w = icon.size;
            d.header.h = icon.size;
            d.header.stride = icon.size * 2;
            d.data_size = (uint32_t)icon.size * icon.size * 3;
            d.data = icon.data;
        }
    }
    // Exact key and size if stored; otherwise the same key at the nearest size, then "cloudy".
    int best = -1, fallback = -1;
    for (int i = 0; i < weather_icon_count; i++) {
        const weather_icon_t& icon = weather_icons[i];
        bool same_key = strcmp(icon.key, key) == 0;
        if (same_key && icon.size == size) return &made[i];
        if (same_key && (best < 0 || LV_ABS(icon.size - size) < LV_ABS(weather_icons[best].size - size))) best = i;
        if (strcmp(icon.key, "cloudy") == 0 && icon.size == size) fallback = i;
    }
    if (best >= 0) return &made[best];
    return fallback >= 0 ? &made[fallback] : &made[0];
}

}  // namespace

lv_obj_t* icon_create(lv_obj_t* parent, int size, const char* key) {
    lv_obj_t* obj = lv_image_create(parent);
    lv_obj_set_user_data(obj, (void*)(intptr_t)size);
    icon_set(obj, key);
    return obj;
}

void icon_set(lv_obj_t* icon, const char* key) {
    int size = (int)(intptr_t)lv_obj_get_user_data(icon);
    const lv_image_dsc_t* wanted = picture(key, size);
    if (lv_image_get_src(icon) != wanted) lv_image_set_src(icon, wanted);
}
